using System.Globalization;
using System.Text;
using System.Text.Json;
using Dapper;
using Npgsql;
using Sigov.Application.Patrimonio;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Patrimonio;

public sealed partial class PatrimonioService
{
    public async Task<long> ProporResponsabilidadeAsync(long tenantId,long entidadeId,long usuarioId,long bemId,PatrimonioTermoInput input,CancellationToken ct)
    { await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var bem=await c.QuerySingleOrDefaultAsync<BemTermo>(new CommandDefinition("select id,codigo_tombo CodigoTombo,descricao,responsavel_usuario_id ResponsavelId,unidade_id UnidadeId,localizacao,situacao from sigov.patrimonio_bem where tenant_id=@Tenant and id=@Bem and not is_deleted for update",new{Tenant=tenantId,Bem=bemId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Bem não encontrado.");if(bem.Situacao=="BAIXADO")throw new InvalidOperationException("Bem baixado não admite nova responsabilidade.");var valido=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.usuario where id=@Responsavel and entidade_id=@Entidade and ativo and not is_deleted)",new{Responsavel=input.ResponsavelId,Entidade=entidadeId},tx,cancellationToken:ct));if(!valido)throw new InvalidOperationException("Responsável não possui vínculo ativo no contexto.");var snapshot=JsonSerializer.Serialize(new{bem.CodigoTombo,bem.Descricao,bem.UnidadeId,bem.Localizacao,ResponsavelPropostoId=input.ResponsavelId,EmitidoEm=DateTimeOffset.UtcNow});var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.patrimonio_termo_responsabilidade(tenant_id,entidade_id,bem_id,responsavel_proposto_id,responsavel_anterior_id,unidade_id,conteudo_snapshot,proposto_por,correlation_id) values(@Tenant,@Entidade,@Bem,@Responsavel,@Anterior,@Unidade,cast(@Snapshot as jsonb),@Usuario,@Correlation) returning id",new{Tenant=tenantId,Entidade=entidadeId,Bem=bemId,Responsavel=input.ResponsavelId,Anterior=bem.ResponsavelId,Unidade=input.UnidadeId??bem.UnidadeId,Snapshot=snapshot,Usuario=usuarioId,Correlation=input.CorrelationId},tx,cancellationToken:ct));await Auditar(c,tx,tenantId,"patrimonio_termo_responsabilidade",id,"PROPOR",null,input,usuarioId,input.CorrelationId,ct);await tx.CommitAsync(ct);return id; }

    public async Task DecidirResponsabilidadeAsync(long tenantId,long entidadeId,long usuarioId,long termoId,PatrimonioTermoDecisaoInput input,CancellationToken ct)
    { if(!input.Aceitar&&string.IsNullOrWhiteSpace(input.Motivo))throw new ArgumentException("Motivo da recusa é obrigatório.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var termo=await c.QuerySingleOrDefaultAsync<TermoEstado>(new CommandDefinition("select id,bem_id BemId,responsavel_proposto_id ResponsavelId,unidade_id UnidadeId,status from sigov.patrimonio_termo_responsabilidade where tenant_id=@Tenant and entidade_id=@Entidade and id=@Id for update",new{Tenant=tenantId,Entidade=entidadeId,Id=termoId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Termo não encontrado.");if(termo.Status!="PENDENTE")throw new InvalidOperationException("O termo já foi decidido.");var status=input.Aceitar?"ACEITO":"RECUSADO";await c.ExecuteAsync(new CommandDefinition("update sigov.patrimonio_termo_responsabilidade set status=@Status,motivo_recusa=@Motivo,decidido_em=now(),vigencia_inicio=case when @Aceitar then now() end,decidido_por=@Usuario where id=@Id",new{Status=status,Motivo=VazioNulo(input.Motivo),input.Aceitar,Usuario=usuarioId,Id=termoId},tx,cancellationToken:ct));if(input.Aceitar){await c.ExecuteAsync(new CommandDefinition("update sigov.patrimonio_termo_responsabilidade set vigencia_fim=now() where tenant_id=@Tenant and bem_id=@Bem and status='ACEITO' and vigencia_fim is null and id<>@Id; update sigov.patrimonio_bem set responsavel_usuario_id=@Responsavel,unidade_id=coalesce(@Unidade,unidade_id),updated_at=now(),updated_by=@Usuario,versao=versao+1 where tenant_id=@Tenant and id=@Bem and situacao<>'BAIXADO'",new{Tenant=tenantId,Bem=termo.BemId,Id=termoId,Responsavel=termo.ResponsavelId,termo.UnidadeId,Usuario=usuarioId},tx,cancellationToken:ct));}await Auditar(c,tx,tenantId,"patrimonio_termo_responsabilidade",termoId,status,null,input,usuarioId,$"termo-{termoId}-{status}",ct);await tx.CommitAsync(ct); }

    public async Task<long> SolicitarTransferenciaAsync(long tenantId,long entidadeId,long usuarioId,long bemId,PatrimonioTransferenciaInput input,CancellationToken ct)
    { if(string.IsNullOrWhiteSpace(input.Justificativa)||string.IsNullOrWhiteSpace(input.LocalizacaoDestino))throw new ArgumentException("Destino e justificativa são obrigatórios.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var bem=await c.QuerySingleOrDefaultAsync<BemEstado>(new CommandDefinition("select unidade_id UnidadeId,responsavel_usuario_id ResponsavelId,localizacao,situacao from sigov.patrimonio_bem where tenant_id=@Tenant and id=@Bem and not is_deleted for update",new{Tenant=tenantId,Bem=bemId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Bem não encontrado.");if(bem.Situacao=="BAIXADO")throw new InvalidOperationException("Bem baixado não pode ser movimentado.");var bloqueio=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select descricao from sigov.manutencao_ordem_servico where tenant_id=@Tenant and alvo_tipo='BEM' and alvo_id=@Bem and status in('APROVADA','EM_EXECUCAO','AGUARDANDO_PECA') order by created_at desc limit 1",new{Tenant=tenantId,Bem=bemId},tx,cancellationToken:ct));if(bloqueio is not null)throw new InvalidOperationException($"Movimentação impedida por manutenção operacional: {bloqueio}");var destino=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.unidade_organizacional where id=@Destino and entidade_id=@Entidade and ativo and not is_deleted)",new{Destino=input.UnidadeDestinoId,Entidade=entidadeId},tx,cancellationToken:ct));if(!destino)throw new InvalidOperationException("Unidade de destino inválida para a entidade atual.");var id=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.patrimonio_transferencia(tenant_id,entidade_id,bem_id,unidade_origem_id,unidade_destino_id,localizacao_origem,localizacao_destino,responsavel_origem_id,responsavel_destino_id,justificativa,solicitada_por,ultima_acao_por,correlation_id) values(@Tenant,@Entidade,@Bem,@Origem,@Destino,@LocalOrigem,@LocalDestino,@RespOrigem,@RespDestino,@Justificativa,@Usuario,@Usuario,@Correlation) returning id",new{Tenant=tenantId,Entidade=entidadeId,Bem=bemId,Origem=bem.UnidadeId,Destino=input.UnidadeDestinoId,LocalOrigem=bem.Localizacao,LocalDestino=input.LocalizacaoDestino.Trim(),RespOrigem=bem.ResponsavelId,RespDestino=input.ResponsavelDestinoId,Justificativa=input.Justificativa.Trim(),Usuario=usuarioId,Correlation=input.CorrelationId},tx,cancellationToken:ct));await Auditar(c,tx,tenantId,"patrimonio_transferencia",id,"SOLICITAR",null,input,usuarioId,input.CorrelationId,ct);await tx.CommitAsync(ct);return id; }

    public async Task OperarTransferenciaAsync(long tenantId,long entidadeId,long usuarioId,long transferenciaId,PatrimonioTransferenciaAcaoInput input,CancellationToken ct)
    { var acao=input.Acao.Trim().ToUpperInvariant();await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var t=await c.QuerySingleOrDefaultAsync<TransferenciaEstado>(new CommandDefinition("select id,bem_id BemId,unidade_destino_id UnidadeDestinoId,localizacao_destino LocalizacaoDestino,responsavel_destino_id ResponsavelDestinoId,status,versao from sigov.patrimonio_transferencia where tenant_id=@Tenant and entidade_id=@Entidade and id=@Id for update",new{Tenant=tenantId,Entidade=entidadeId,Id=transferenciaId},tx,cancellationToken:ct))??throw new KeyNotFoundException("Movimentação não encontrada.");var esperado=acao switch{"AUTORIZAR"=>"SOLICITADA","EXPEDIR"=>"AUTORIZADA","RECEBER"=>"EM_TRANSITO","RECUSAR"=>"EM_TRANSITO","CANCELAR" when t.Status is "SOLICITADA" or "AUTORIZADA"=>t.Status,_=>string.Empty};if(esperado.Length==0||t.Status!=esperado)throw new InvalidOperationException($"A ação {acao} não é permitida no estado {t.Status}.");if((acao is "RECUSAR" or "CANCELAR")&&string.IsNullOrWhiteSpace(input.Motivo))throw new ArgumentException("Informe o motivo.");var novo=acao switch{"AUTORIZAR"=>"AUTORIZADA","EXPEDIR"=>"EM_TRANSITO","RECEBER"=>"CONCLUIDA","RECUSAR"=>"RECUSADA",_=>"CANCELADA"};var changed=await c.ExecuteAsync(new CommandDefinition("update sigov.patrimonio_transferencia set status=@Novo,motivo_recusa=@Motivo,autorizada_em=case when @Acao='AUTORIZAR' then now() else autorizada_em end,expedida_em=case when @Acao='EXPEDIR' then now() else expedida_em end,recebida_em=case when @Acao='RECEBER' then now() else recebida_em end,cancelada_em=case when @Acao='CANCELAR' then now() else cancelada_em end,ultima_acao_por=@Usuario,versao=versao+1 where id=@Id and versao=@Versao",new{Novo=novo,Motivo=VazioNulo(input.Motivo),Acao=acao,Usuario=usuarioId,Id=transferenciaId,Versao=input.Versao},tx,cancellationToken:ct));if(changed==0)throw new InvalidOperationException("A movimentação foi alterada por outro operador; atualize a tela.");if(acao=="RECEBER"){await c.ExecuteAsync(new CommandDefinition("update sigov.patrimonio_bem set unidade_id=@Unidade,localizacao=@Localizacao,responsavel_usuario_id=coalesce(@Responsavel,responsavel_usuario_id),updated_at=now(),updated_by=@Usuario,versao=versao+1 where tenant_id=@Tenant and id=@Bem; insert into sigov.patrimonio_movimentacao(tenant_id,bem_id,unidade_origem_id,unidade_destino_id,responsavel_destino_id,localizacao_destino,tipo_movimentacao,justificativa,data_movimentacao,usuario_id,correlation_id) select tenant_id,bem_id,unidade_origem_id,unidade_destino_id,responsavel_destino_id,localizacao_destino,'TRANSFERENCIA',justificativa,now(),@Usuario,'transferencia-'||id from sigov.patrimonio_transferencia where id=@Id",new{Unidade=t.UnidadeDestinoId,Localizacao=t.LocalizacaoDestino,Responsavel=t.ResponsavelDestinoId,Usuario=usuarioId,Tenant=tenantId,Bem=t.BemId,Id=transferenciaId},tx,cancellationToken:ct));}await Auditar(c,tx,tenantId,"patrimonio_transferencia",transferenciaId,acao,t,input,usuarioId,$"transferencia-{transferenciaId}-{input.Versao}",ct);await tx.CommitAsync(ct); }

    public async Task<PatrimonioTermoDto?> ObterTermoAsync(long tenantId,long entidadeId,long termoId,CancellationToken ct)
    { await using var c=factory.CreateConnection();return await c.QuerySingleOrDefaultAsync<PatrimonioTermoDto>(new CommandDefinition("select t.id,t.bem_id BemId,t.responsavel_proposto_id ResponsavelPropostoId,coalesce(p.nome,u.login) ResponsavelProposto,t.status,t.conteudo_snapshot::text ConteudoSnapshot,t.motivo_recusa MotivoRecusa,t.proposto_em PropostoEm,t.decidido_em DecididoEm,t.vigencia_inicio VigenciaInicio,t.vigencia_fim VigenciaFim from sigov.patrimonio_termo_responsabilidade t join sigov.usuario u on u.id=t.responsavel_proposto_id left join sigov.pessoa p on p.id=u.pessoa_id where t.tenant_id=@Tenant and t.entidade_id=@Entidade and t.id=@Id",new{Tenant=tenantId,Entidade=entidadeId,Id=termoId},cancellationToken:ct)); }
}
